-- =====================================================================
-- seed-candidates.sql
-- Compatible candidate seed data for the v1.1 candidates table.
--
-- Columns used (surviving after 036 trim):
--   id, student_id, election_period_id, surname, given_name, middle_name,
--   extension_name, grade_level, position, party_id, gender, date_of_birth,
--   age, email, mobile_number, landline, home_address, parent_guardian_name,
--   parent_guardian_contact, picture_url, leadership_profile,
--   doc_application_form, doc_introductory_profile, doc_screening_form,
--   doc_report_card, doc_good_moral_cert, doc_eaf_front, doc_eaf_back,
--   eaf_front_url, eaf_back_url, position_approval_status, status,
--   forwarded_at, reviewed_at, submitted_at, rejection_reason,
--   rejection_details, rejection_tier
--
-- Columns REMOVED by 036 (do NOT appear here):
--   forwarded_by, reviewed_by
--
-- Run in Supabase Dashboard > SQL Editor.  Safe to re-run (INSERT ...
-- ON CONFLICT DO NOTHING on the (student_id, election_period_id) unique
-- constraint).
--
-- Requires migration 052 and the party rows from seed-parties.sql, because
-- the closing UPDATEs resolve each candidate's party inside its own election
-- period.  Order: 052 -> seed-parties -> seed-candidates.
-- =====================================================================

set search_path = public, extensions;

INSERT INTO public.candidates (
  id, student_id, election_period_id, surname, given_name, middle_name,
  extension_name, grade_level, position, party_id, gender, date_of_birth,
  age, email, mobile_number, landline, home_address, parent_guardian_name,
  parent_guardian_contact, picture_url, leadership_profile,
  doc_application_form, doc_introductory_profile, doc_screening_form,
  doc_report_card, doc_good_moral_cert, doc_eaf_front, doc_eaf_back,
  eaf_front_url, eaf_back_url, position_approval_status, status,
  forwarded_at, reviewed_at, submitted_at, rejection_reason,
  rejection_details, rejection_tier
) VALUES
  ('00e928ec-4041-4e00-bfae-969531a53e6e', '7cb2380d-cdce-414f-8075-529b9978a575', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Dela Cruz', 'Gabriel', 'Nathaniel', null, 'Grade 12', 'Grade 12 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2008-03-21', 17, 'gabrieldelacruz@gmail.com', '09205551545', null, 'Purok 1 Brgy. Bagong Silang I Labo, Camarines Norte', 'Antonio N. Dela Cruz', '09205551545', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_1cbae83b-3e63-416f-9278-43759f3846d2_1786890126995.jpg', '{"skills": ["Values-Oriented", "Service-Oriented"], "qualities": "I believe discipline, reliability, fairness, adaptability, and problem-solving can help me become a great leader. Discipline allows me to stay focused and organized when handling responsibilities. Reliability helps build trust because people need representatives who can be counted on. Fairness ensures that decisions are made based on what is beneficial rather than personal relationships. Adaptability allows me to respond appropriately when circumstances change. Problem-solving helps me focus on solutions and encourage others to work together during difficult situations. I also believe that a great leader should be willing to listen and admit when they are wrong. Leadership requires continuous learning, and no person can solve every problem alone. I want to lead through consistent actions, cooperation, accountability, and respect for every student in the school community.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government as a highly organized organization that students can trust and rely on. I want it to have clear systems for collecting student concerns, planning projects, documenting activities, and evaluating results. Student leaders should communicate regularly with learners instead of only communicating during major school events. I also want the organization to develop programs related to academic support, student welfare, environmental responsibility, leadership, and community service. Future officers should be able to review previous projects and continue successful programs instead of starting from the beginning every school year. I believe transparency and accountability should be important parts of student government. My vision is a Learner Government that focuses on sustainable improvements and gives students meaningful opportunities to participate in school leadership and decision-making.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have experienced different situations in school where planning and cooperation were necessary. Discipline helps me organize my responsibilities and complete tasks on time. Reliability allows me to become someone classmates can depend on during group activities. Fairness helps me consider different opinions before making decisions. Adaptability is useful when schedules change or unexpected problems affect a project. Problem-solving helps me analyze challenges and consider possible solutions instead of immediately giving up. These qualities are especially useful for student leadership because Learner Government officers must coordinate projects and communicate with different groups. I believe these skills will help me handle responsibilities more effectively and contribute to an organization that focuses on practical solutions to student concerns.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('01061fdb-f1b4-4eb9-970a-d4b119303522', 'bf02f471-67b0-47a9-8a65-88a2c7be7919', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Navarro', 'Isabella', 'Mae', null, 'Grade 9', 'PIO', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2010-05-27', 15, 'isabellanavarro@gmail.com', '09175550768', null, 'Purok 9 Brgy. Bagumbayan Paracale, Camarines Norte', 'Carlos M. Navarro', '09175550768', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_49c5d6c8-4101-4321-b75b-d129e1f69317_1786891036718.jpg', '{"skills": ["Values-Oriented", "Motivational", "Communication", "Service-Oriented"], "qualities": "My ability to listen, creativity, responsibility, determination, and cooperation are qualities that I believe can help me become a great leader. Listening helps me understand different perspectives before making decisions. Creativity allows me to consider solutions beyond the usual approaches. Responsibility ensures that I take commitments seriously and complete assigned tasks. Determination helps me continue working when challenges occur. Cooperation reminds me that leadership is not an individual activity. A leader needs other people to transform ideas into successful projects. I also believe that humility is important because leaders should recognize the contributions of others. I want to create an environment where students are comfortable sharing their ideas and where mistakes are treated as opportunities for improvement. My goal is to help students become more confident participants in their school community.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become a student organization that encourages participation from everyone, including students who are normally quiet or less involved in school activities. In three years, I want students to feel that their ideas are welcome and that their representatives are accessible. The organization should create programs involving academics, arts, sports, environmental activities, community service, and student welfare. I also want future leaders to use student feedback when deciding which programs should be continued or improved. Transparency should be practiced by communicating project objectives and results clearly. I hope the Learner Government will become an environment where young people can practice leadership, teamwork, problem-solving, and responsible decision-making. Its success should be measured by how much it helps students and strengthens the school community.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I often participate in group activities where listening and cooperation are necessary. I have learned that understanding what other people need can make teamwork more successful. My creativity helps me suggest different approaches when a group encounters a problem. Responsibility helps me manage school requirements and assigned tasks. Determination is especially useful when projects require repeated effort or revisions. I believe these qualities would be useful in student government because officers need to understand student concerns, plan activities, communicate with others, and continue improving their projects. I also believe being a good listener will help me avoid making assumptions about what students need. Instead, I can gather information and use their feedback to help create programs that are more relevant and useful.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('014eeede-3b99-4be0-ac72-5fbf00e7d3cf', '9ed828ff-6286-4b4d-857a-369a632ab92d', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Santos', 'Maria', 'Angelica', null, 'Grade 8', 'Vice President', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2010-03-16', 15, 'mariasantos@gmail.com', '09903162010', null, 'Purok 2 Brgy. Bibirao Daet, Camarines Norte', 'Cristina A. Santos', '09903162010', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_ce873408-5ab1-4343-91ee-9f79663b8d4b_1786897076780.jpg', '{"skills": ["Values-Oriented", "Motivational", "Communication", "Service-Oriented"], "qualities": "My teamwork, patience, adaptability, communication, initiative, and respect are qualities that can help me become a great leader. Teamwork helps me understand that leadership is a shared responsibility. Patience allows me to listen carefully when people have different opinions. Adaptability helps me remain effective when circumstances change. Communication allows me to explain information and understand student concerns. Initiative encourages me to take action instead of waiting for someone else to solve every problem. Respect ensures that I treat everyone properly regardless of their position or opinion. I want to be a leader who encourages cooperation and helps other students become confident enough to participate in activities and express their ideas.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become a highly coordinated organization where every officer and representative understands their responsibilities. In three years, I hope students will see the organization as approachable and responsive. I want regular consultations between representatives and their grade levels so that student concerns can be identified early. I also envision academic support programs, environmental campaigns, leadership activities, sports programs, and projects that encourage students to cooperate. The Learner Government should not only organize events but should also evaluate whether those activities actually benefit students. I want future officers to inherit an organized system that allows them to continue successful programs while improving areas that need attention.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I often work with classmates during group projects and school activities. I have learned that every person has different strengths and working styles, so cooperation requires patience and communication. I try to make sure that everyone in a group has an opportunity to contribute. When unexpected problems occur, I try to focus on possible solutions instead of becoming discouraged. These abilities would be useful as Vice President because the position requires close coordination with the President, officers, representatives, and students. I would help make sure that different parts of the organization work together effectively. I would also encourage officers to communicate with one another and support each other''s responsibilities.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('0799e325-09ce-4d91-8152-45d9d5bfc3a5', '808f703e-b7a9-4276-bff4-1dea9887dcfc', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Villanueva', 'Mark', 'Anthony', null, 'Grade 10', 'PRO', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2010-01-11', 16, 'markvillanueva@gmail.com', '09215550657', null, 'Purok 5 Brgy. Caawigan Talisay, Camarines Norte', 'Lorna A. Villanueva', '09215550657', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_da4a0bc4-ffa1-4501-9e98-48c11f3b9f19_1786891166854.jpg', '{"skills": ["Values-Oriented", "Problem Solving", "Communication", "Service-Oriented"], "qualities": "I believe honesty, dedication, initiative, patience, and communication can make me a great leader. Honesty helps establish trust between a leader and the people they represent. Dedication ensures that responsibilities are taken seriously and completed even when challenges occur. Initiative allows me to identify possible solutions instead of waiting for problems to become larger. Patience helps me work respectfully with people who have different opinions or approaches. Communication allows me to explain ideas clearly and understand feedback from others. I also believe a great leader should be willing to learn and accept criticism. Nobody can improve without feedback. I want to use these qualities to create a student government where people feel comfortable sharing ideas and where every member understands that leadership should be focused on service rather than personal recognition.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government as an organization that students recognize as an effective representative of their interests. I want it to have consistent communication channels where students can submit concerns and receive updates about how those concerns are being addressed. I also want student leaders to focus on projects that create measurable benefits instead of organizing activities simply because they are traditional. Academic support, student welfare, environmental programs, leadership development, and community service should all be considered important areas. I also believe the Learner Government should maintain records of previous projects and recommendations so future officers can continue successful programs. My vision is an organization that values transparency, accountability, teamwork, and continuous improvement while encouraging more students to participate in school governance.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('08431a10-d14b-411d-abf1-7093579c4235', '9a9d1546-b85c-4525-a127-75a6040dc4de', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Bautista', 'Carlo', 'Vincent', null, 'Grade 8', 'Grade 8 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2012-10-16', 13, 'carlobautista@gmail.com', '09185551091', null, 'Purok 1 Brgy. Awitan Daet, Camarines Norte', 'Ramon V. Bautista', '09185551091', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_a2010b04-4c95-43d7-9a1a-4c65539cd8ad_1786890611704.jpg', '{"skills": ["Values-Oriented", "Communication"], "qualities": "Reliability, discipline, initiative, respect, and problem-solving are qualities that I believe can make me a great leader. Reliability means people can trust me to complete responsibilities and communicate honestly when problems occur. Discipline helps me remain organized and focused on goals. Initiative allows me to identify opportunities for improvement and take action without always waiting for instructions. Respect allows me to work with people who have different opinions and backgrounds. Problem-solving helps me focus on practical solutions when challenges arise. I also believe a leader should understand their limitations and seek advice when necessary. I want to become a leader who does not simply promise change but develops realistic plans, works with others, and evaluates the results. Leadership should be demonstrated through consistent actions and accountability.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government having stronger systems for communication, project planning, accountability, and student participation. I want student leaders to have clear responsibilities and measurable objectives for their projects. Students should also have reliable ways to provide suggestions and report concerns. I believe the organization should focus on practical programs that directly benefit learners, including academic support, environmental initiatives, leadership activities, and student welfare programs. Project results should be documented so future leaders can determine which programs were effective. I also hope that student representatives will develop stronger relationships with teachers and administrators so problems can be addressed collaboratively. My vision is a Learner Government that is organized, transparent, responsible, and focused on creating sustainable improvements instead of temporary activities.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('0aed7327-6ed5-4e0f-a71c-29ef597e87de', '239b82fb-736f-4f8f-86ec-8b5ff5135317', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Aquino', 'Nathaniel', 'James', null, 'Grade 11', 'Protocol Officer', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2009-08-30', 16, 'nathaniel@gmail.com', '09288283387', null, 'Brgy. San Isidro Talisay, Camarines Norte', 'Jaoe A. Uane', '09928388337', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_65e9a67b-fa12-4366-b688-d462d08c3090_1786897578858.jpg', '{"skills": ["Problem Solving"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Hsidn", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Ksksk", "makabansaProject": "Kd", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Jzn", "makaDiyosDescription": "Ksm", "makabansaDescription": "Sk", "makakalikasanProject": "Ken", "makakalikasanDescription": "Ko"}', true, true, true, true, true, null, null, 'low'),
  ('1384aced-1d7b-41ac-95fc-1ce4c95a1999', '422f2f34-8f9b-4351-978d-33a3129a5986', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Castillo', 'Lucas', 'Andrei', null, 'Grade 9', 'Grade 9 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2011-08-11', 14, 'lucas@gmail.com', '09937848374', null, 'Brgy. Fabrica San Vicente, Camarines Norte', 'Ula A. Dela', '09937483836', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_265606ae-365c-4a5f-9a3c-63b980ed4ac3_1786898165921.jpg', '{"skills": ["Motivational"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jfidj", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Kfi", "makabansaProject": "Krirk", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Idi", "makaDiyosDescription": "Jkfk", "makabansaDescription": "Djxn", "makakalikasanProject": "Kfi", "makakalikasanDescription": "Iri"}', true, true, true, true, true, null, null, 'low'),
  ('17d11ef2-b5b5-4eb9-b2af-61a94a284217', '587f1286-f206-4923-8b61-ba92d8fc0950', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Garcia', 'Angela', 'N', null, 'Grade 9', 'Grade 9 Representative', '8a513434-048e-4235-85a4-a259389df184', 'Female', '2003-01-01', 23, 'grade9@gmail.com', '09956666666', null, 'RRR Brgy. Fabrica San Vicente, Camarines Norte', 'G9 N. Nime', '09945654643', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_5a93bb43-a99e-44cc-a823-37a2d3a5561e_1783434580070.jpg', '{"skills": ["Goal-Oriented", "Communication", "Service-Oriented"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "i", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaDiyosProject": "p", "makabansaProject": "r", "skillsExplanation": "These skills are applicable to me because they reflect the way I approach both my academic responsibilities and my interactions with others. Whenever I am given a task, I make sure to complete it with dedication, organization, and attention to detail. I enjoy collaborating with classmates, sharing ideas, and finding solutions to problems through teamwork. I am also willing to step forward when leadership is needed while remaining humble enough to accept suggestions and learn from mistakes. I understand that leadership requires patience, responsibility, and effective communication, and I continuously work to improve these qualities. My experiences in school have taught me the importance of being reliable, respectful, and compassionate. These skills enable me to serve not only as a leader but also as someone who genuinely represents and supports the interests of every student.", "makaTaoDescription": "u", "makaDiyosDescription": "o", "makabansaDescription": "e", "makakalikasanProject": "y", "makakalikasanDescription": "t"}', true, true, true, true, true, null, null, 'low'),
  ('17d9869a-a842-4437-9587-e31d920ff17b', 'dda32f01-6cf7-4a56-8934-1a8f8b2bc7f4', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Navarro', 'Gabriel', 'Ethan', null, 'Grade 9', 'President', null, 'Male', '2009-10-17', 16, 'gabrielnavarro@gmail.com', '09917102009', null, 'Purok 2 Brgy. Pamorangon Daet, Camarines Norte', 'Roberto E. Navarro', '09917102009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_0bc38684-978a-4afa-b190-5db7ccad88bb_1786898884551.jpg', '{"skills": ["Motivational", "Goal-Oriented", "Values-Oriented", "Service-Oriented", "Communication"], "qualities": "I believe integrity, responsibility, empathy, determination, communication, confidence, and humility can make me a great leader. Integrity allows me to remain honest and fair when making decisions. Responsibility reminds me that accepting a leadership position means being accountable for my actions and commitments. Empathy helps me understand different student perspectives and concerns. Determination allows me to continue working toward goals despite challenges. Communication helps me listen and explain ideas clearly. Confidence allows me to represent students when their concerns need to be addressed. Finally, humility reminds me that a leader does not have all the answers. I am willing to listen to other people, accept constructive criticism, admit mistakes, and learn from them. I want to lead by example and demonstrate that leadership is ultimately about serving others.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that is trusted, transparent, inclusive, and focused on meaningful student service. I want students to feel comfortable approaching their representatives with concerns and suggestions. I envision regular student consultations where officers can identify issues involving academics, student activities, school environment, and student welfare. I also want future officers to maintain proper documentation of projects so successful programs can continue even after elections. Technology can be used to improve communication and collect feedback, but personal interaction should remain important. My vision is for the Learner Government to become an organization where students do not simply vote for leaders but actively participate in creating projects and solutions. I want each administration to leave behind improvements that future leaders can build upon.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have learned through group activities, academic projects, and school programs that leadership requires both communication and cooperation. I try to listen carefully when classmates share their ideas or concerns before making decisions. I also take responsibility for tasks assigned to me because I understand that other people may depend on my work. My determination helps me continue working when a project becomes difficult or when the first solution does not work. I believe empathy is particularly useful because a student leader should understand different perspectives instead of assuming that one solution will work for everyone. If elected, I would use these skills to represent students fairly, coordinate with officers, and help develop programs that respond to actual student needs rather than personal preferences.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('1c94f264-d49b-4ef7-aa35-899da039a894', '2fa2d957-2647-4493-8cde-25a452fe5142', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Ramos', 'Nicole', 'E', null, 'Grade 11', 'Grade 11 Representative', null, 'Female', '2005-02-09', 21, 'grade11@gmail.com', '09987612345', null, 'Pilla Brgy. Bayawas Pilar, Sorsogon', 'G11 E. Eleven', '09987612345', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_a31a668b-43cb-4673-9f68-17d65f8713f6_1783437996425.jpg', '{"skills": ["Communication", "Service-Oriented", "Values-Oriented"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "e", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaTaoDescription": "r", "makaDiyosDescription": "w", "makabansaDescription": "i", "makakalikasanProject": "t", "makakalikasanDescription": "y"}', true, true, true, true, true, null, null, 'low'),
  ('2244ad01-7414-424a-aef5-9607a6ecf238', '47936507-77c8-470b-a85f-a80e6d0cc063', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Ortega', 'Francis', 'Miguel', null, 'Grade 10', 'Auditor', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2009-08-14', 16, 'francisortega@gmail.com', '09908142009', null, 'Purok 2 Brgy. Bagasbas Daet, Camarines Norte', 'Carmen M. Ortega', '09908142009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_afcdf303-7c92-4d4f-bf01-a6b7a73ebb49_1786897406125.jpg', '{"skills": ["Motivational", "Problem Solving", "Communication"], "qualities": "My critical thinking, fairness, patience, objectivity, responsibility, and attention to detail can help me become a great leader. Critical thinking allows me to examine problems carefully before making conclusions. Fairness helps me consider different perspectives. Patience allows me to gather enough information before making judgments. Objectivity helps me focus on facts rather than personal relationships. Responsibility reminds me to fulfill my duties and remain accountable. Attention to detail helps me identify errors that may otherwise be overlooked. I believe a great leader should also be willing to hear criticism. I want to contribute to a culture where accountability is viewed positively and where mistakes become opportunities to improve organizational systems.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to have a strong culture of accountability and transparency. In three years, I want officers to understand that reviewing projects and records is a normal part of responsible leadership. Every program should have proper planning, documentation, and evaluation. I also want officers to become comfortable receiving constructive criticism because feedback can help improve future projects. The organization should maintain records that future leaders can use when planning their own activities. I hope students will trust their Learner Government because they can see that officers take their responsibilities seriously. Accountability should not be something that happens only when problems occur; it should be part of everyday operations.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I naturally like checking information and comparing it against requirements. When completing school assignments, I review instructions and check my work before submitting it. This habit can be useful when reviewing records, reports, and organizational procedures. I understand that an Auditor must remain objective and focus on evidence. If I discover an issue, I would communicate it respectfully and allow the responsible officer to explain the situation. I believe auditing should be constructive. Its purpose should be to strengthen accountability and prevent future problems. These skills would help me perform my responsibilities carefully while maintaining professional relationships with the other members of the Learner Government.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('2513e289-ea77-4b71-a4b6-d44b28c7b45b', '6a7368b3-81c9-472f-b6aa-bf78960cbdf4', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Flores', 'Maria', 'Celeste', null, 'Grade 11', 'Grade 11 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2009-10-08', 16, 'mariaflores@gmail.com', '09185551434', null, 'Purok 3 Brgy. Barangay II (Pob.) Mercedes, Camarines Norte', 'Roberto C. Flores', '09185551434', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_5523bc93-5c8d-4ca4-9b6b-e67efa8e0a9e_1786890240394.jpg', '{"skills": ["Goal-Oriented", "Values-Oriented", "Motivational"], "qualities": "I believe empathy, honesty, creativity, communication, and responsibility are qualities that can help me become a great leader. Empathy allows me to consider the experiences and concerns of other students. Honesty helps establish trust and encourages people to believe that their representatives are being truthful. Creativity helps me develop new ideas when existing approaches are not effective. Communication allows me to explain plans clearly and listen to feedback. Responsibility ensures that I take my commitments seriously and remain accountable for my actions. I also believe a great leader should be humble and willing to accept criticism. No leader can improve without learning from others. I want to become a leader who encourages participation, respects different opinions, and works together with other students to create positive and sustainable changes in our school.", "makaTaoProject": "S", "threeYearVision": "My vision for the Learner Government in three years is an organization that is inclusive, transparent, active, and trusted by students. I want every student to feel that they have an opportunity to express their opinions, regardless of their academic performance or level of involvement in school organizations. The Learner Government should organize programs that support academics, student welfare, environmental protection, leadership development, and community service. I also want representatives to regularly collect student feedback and use it when planning future programs. Technology can help make communication faster through online surveys, announcements, and feedback platforms. I hope future officers will properly document their projects so successful programs can be continued and improved. Ultimately, I want the Learner Government to help students develop confidence, responsibility, cooperation, and leadership skills.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I often work with different classmates during school activities and group projects. I have learned that effective teamwork requires understanding and respecting different opinions. My communication skills help me explain ideas and ask questions when something is unclear. Empathy helps me understand why classmates may have different concerns or priorities. Creativity allows me to suggest alternative approaches when a group encounters a problem. Responsibility helps me complete tasks and meet deadlines. These qualities can be applied to student leadership because the Learner Government needs representatives who can communicate with many different students and coordinate with teachers and administrators. I believe these skills can help me understand student concerns more effectively and contribute to projects that provide meaningful benefits to the school community.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('32e3c747-bb93-4cee-8045-94157f64fbad', 'df712bb2-a5c1-4599-9ae2-ac994835d6ff', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Torres', 'Mikaela', 'Rose', null, 'Grade 10', 'Grade 10 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2010-12-10', 15, 'mikaela@gmail.com', '09387383737', null, 'Brgy. Awitan Labo, Camarines Norte', 'Lauea S. Torres', '09928383798', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_141b5469-d666-46b2-ab8f-96b1109303b0_1786897965231.jpg', '{"skills": ["Problem Solving"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jsksk", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Jwk.", "makabansaProject": "Jsjdj", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Jsjdk", "makaDiyosDescription": "Jsks", "makabansaDescription": "Jxjdj", "makakalikasanProject": "Jsjdk", "makakalikasanDescription": "Sieii"}', true, true, true, true, true, null, null, 'low'),
  ('33282927-7973-499a-a0b8-f9521c5646fb', '5932d83e-e453-4d7f-a71b-003e3d966db7', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Cabrera', 'Matthew', 'Luis', null, 'Grade 8', 'PIO', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2009-09-02', 16, 'matthewcabrera@gmail.com', '09909022009', null, 'Purok 1 Brgy. Bagasbas Daet, Camarines Norte', 'Rosalie L. Cabrera', '09909022009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_2aa10635-bf2b-416b-bbc5-b9158ca6a14e_1786897633306.jpg', '{"skills": ["Values-Oriented", "Communication"], "qualities": "My friendliness, empathy, respect, confidence, communication, and cooperation are qualities that can help me become a great leader. Friendliness helps students feel comfortable approaching me. Empathy allows me to understand different experiences and concerns. Respect ensures that I treat people properly even when they disagree with me. Confidence allows me to represent students in different situations. Communication helps me explain ideas and understand what others are saying. Cooperation reminds me that student government is a team effort. I believe a great leader should make people feel valued and heard. My goal is to build positive relationships and encourage students to participate rather than making leadership about personal recognition.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become an organization with strong relationships throughout the school community. In three years, I hope students will feel comfortable approaching their representatives with ideas, concerns, and suggestions. I want activities to encourage cooperation between different grade levels and student groups. I also envision stronger relationships between the Learner Government and school personnel. Student leaders should communicate respectfully and professionally while still representing student interests. I want the organization to promote school spirit, inclusivity, teamwork, and participation. A strong Learner Government should not separate itself from the students. Instead, it should build bridges that encourage everyone to work together.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I enjoy interacting with classmates and participating in activities that require cooperation. I have learned that positive relationships depend on listening and respecting different opinions. As PRO, I would communicate with students and help represent the Learner Government appropriately during school activities. I would also help welcome students and encourage them to participate in programs. My empathy would help me understand concerns, while my communication skills would help me explain information clearly. I believe public relations should be based on trust rather than simply creating a good appearance. Students should feel that their representatives genuinely care about their concerns and are willing to communicate with them.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('33e25998-68f0-4691-be40-e1022afa977a', 'ea79a300-12fb-4144-8105-d27f01053dd7', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Santos', 'Adrian', 'Miguel', null, 'Grade 12', 'President', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2009-03-09', 17, 'adrian.santos@gmail.com', '09916363627', null, 'Brgy. Camambugan Daet, Camarines Norte', 'Marites S. Santos', '09927272762', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_d85b434d-a56f-47c7-9b15-bcff3195e5d1_1786896429922.jpg', '{"skills": ["Motivational", "Communication", "Goal-Oriented", "Service-Oriented", "Values-Oriented", "Problem Solving"], "qualities": "As an inspiring student leader, I possess responsibility, determination, honesty, and compassion. I am willing to listen to others and understand their concerns before making decisions. I believe that a good leader should lead by example, remain respectful, and treat everyone fairly regardless of their differences. I am also committed to teamwork because I believe that great results are achieved when people work together. When challenges arise, I stay calm, learn from mistakes, and look for practical solutions. Most importantly, I am willing to serve, support, and encourage my fellow learners while continuously improving myself as a leader and as a person.", "makaTaoProject": "Kaguran", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Kapatiran", "makabansaProject": "Heyy", "skillsExplanation": "These skills are applicable to me because they reflect the qualities I need as a responsible and effective student leader. Communication helps me express ideas clearly and understand the concerns of my fellow learners. Leadership allows me to guide others, make responsible decisions, and encourage teamwork. Time management helps me balance my academic responsibilities with leadership duties. Problem-solving enables me to handle challenges calmly and find practical solutions. I also value adaptability because student organizations face different situations that require flexibility. Most importantly, these skills will help me serve others, build trust, promote cooperation, and contribute positively to our school community.", "makaTaoDescription": "Hahah", "makaDiyosDescription": "Well good", "makabansaDescription": "Kajaj", "makakalikasanProject": "Sawakz", "makakalikasanDescription": "Hahhah"}', true, true, true, true, true, null, null, 'low'),
  ('34555951-e703-4d06-ad0b-5a721326e600', '391918bc-83d3-445b-b17c-b4d6cce7120e', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Flores', 'Gabriel', 'Thomas', null, 'Grade 11', 'PIO', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2009-11-12', 16, 'gabriel@gmail.com', '09937739278', null, 'Brgy. Guinatungan Basud, Camarines Norte', 'Laro W. Qos', '09928747484', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_65eb22c0-11c1-4576-9857-e323ab9e6651_1786897312172.jpg', '{"skills": ["Problem Solving"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Lamdm", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Cinne", "makabansaProject": "Jd", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "erg", "makaDiyosDescription": "Jcmk", "makabansaDescription": "Nzn", "makakalikasanProject": "Jdk", "makakalikasanDescription": "Kd"}', true, true, true, true, true, null, null, 'low'),
  ('34b42506-ef0b-4e3b-b0e6-8a1eef8aeac3', 'fb306ada-e307-45c6-a989-66343282636c', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Cruz', 'Miguel', 'E', null, 'Grade 7', 'Grade 7 Representative', '8a513434-048e-4235-85a4-a259389df184', 'Male', '2001-02-01', 25, 'grade7@gmail.com', '09981273675', null, 'D Brgy. Barangay III (Pob.) Malilipot, Albay', 'G7 G. GGG', '09912436128', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_9bff18c0-3f4d-49a9-a039-7acb7057e914_1783426988844.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "3", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaTaoDescription": "4", "makaDiyosDescription": "2", "makabansaDescription": "8", "makakalikasanProject": "5", "makakalikasanDescription": "6"}', true, true, true, true, true, null, null, 'low'),
  ('36e7d2bc-e310-41e8-9c8e-78bf1e2bc419', '0208f7b8-be48-47f2-8e07-8d3293d60a7d', 'f48e5ec2-4e96-4731-94b2-3ac0825edf0d', 'Carlos', 'Reyes', 'h', null, 'Grade 12', 'Vice President', '7162ee76-5bb6-43c2-8126-917c0e2cc9e6', 'Male', '1998-11-01', 27, 'hihi@gmail.com', '09876543211', null, '1, Baclayon, Bacacay, Albay, Region V', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_09e6218b-8518-4cec-8916-a7fa3e021f1e_1778351310340.jpg', '{"skills": ["Motivational", "Problem Solving", "Communication", "Service-Oriented"], "qualities": "s", "threeYearVision": "s", "skillsExplanation": "s"}', true, true, true, true, true, null, null, 'low'),
  ('39f352c4-02af-40b3-9617-11e563eff3b5', '1a0a3f56-4f4c-4372-a717-23c5a2f546f1', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Pineda', 'Leah', 'Nicole', null, 'Grade 9', 'Grade 9 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2012-10-28', 13, 'leahpineda@gmail.com', '09910182012', null, 'Purok 3 Brgy. Dogongan Daet, Camarines Norte', 'Roberto N. Pineda', '09910282012', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_7862ad25-b55b-45a9-a967-815f98e41e88_1786898129641.jpg', '{"skills": ["Values-Oriented", "Goal-Oriented"], "qualities": "My determination, fairness, patience, perseverance, responsibility, and communication skills can help me become a great leader. Determination allows me to continue working toward goals even when progress is slow. Fairness helps me consider different student perspectives. Patience allows me to listen carefully instead of making rushed decisions. Perseverance helps me continue when problems become difficult. Responsibility reminds me to complete my commitments and communicate honestly. Communication allows me to understand students and represent them properly. I believe leadership should be based on service rather than popularity. I want to focus on practical actions that can benefit students and encourage my classmates to participate in improving our school community.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that focuses on meaningful student concerns and practical improvements. I want representatives to communicate regularly with their grade levels and collect feedback about school programs. I envision academic support activities, environmental campaigns, leadership programs, student engagement projects, and community initiatives. Every project should have a clear purpose and should be evaluated after completion. This would help future officers understand what worked and what needs improvement. I also want students to understand that student government is not only about elections and events. It should provide opportunities for students to practice responsibility, cooperation, communication, and service to their community.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because school projects have taught me that successful results require commitment and cooperation. I try to remain focused when group tasks become difficult. Communication helps me prevent misunderstandings and understand what other students need. As Grade 9 Representative, I would listen to my classmates and identify concerns that should be communicated to the Learner Government. I would also encourage students to participate in school programs. My fairness would help me represent different perspectives, while my determination would help me follow through with responsibilities. I want to be a representative who does not simply listen to concerns but also helps communicate them to the appropriate officers.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('3ae54657-0c3a-4a1b-a90d-cf9c36a8a481', '7a7a7b73-82db-43db-a727-eeabff0523e7', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Santos', 'Daniel', 'Patrick', null, 'Grade 12', 'Secretary', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2008-11-05', 17, 'danielsantos@gmail.com', '09185550324', null, 'Purok 3 Brgy. Anahaw (Pob.) Labo, Camarines Norte', 'Elena P. Santos', '09185550324', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_388b250f-66be-410a-88a6-b6ef65de8b75_1786891842787.jpg', '{"skills": ["Values-Oriented", "Communication", "Problem Solving", "Service-Oriented"], "qualities": "I believe discipline, accountability, determination, fairness, and teamwork are qualities that can make me an effective leader. Discipline allows me to stay focused on responsibilities even when there are distractions or difficulties. Accountability means that I am willing to accept the consequences of my decisions and learn from mistakes. Determination helps me continue pursuing a goal even when progress is slow. Fairness is important because leaders should not favor people based on friendships or popularity. Finally, teamwork allows me to recognize that leadership is a shared responsibility. I believe a great leader should make other people feel valued and capable rather than making everything about themselves. By combining these qualities, I hope to create an environment where students feel encouraged to participate and contribute their own ideas.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government becoming an organization that students actively trust and support. I want it to become more focused on listening to students and responding to their actual needs. The organization should provide opportunities for students to participate in academic, cultural, environmental, and community programs. I also believe that transparency should become an important part of student leadership. Students should know what projects are being planned, how activities are being implemented, and what results were achieved. Future leaders should also maintain proper documentation so successful programs can continue even after new officers are elected. My vision is for a Learner Government that does not only organize events but also develops responsible young leaders who understand service, accountability, teamwork, and the importance of representing the student body.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have experienced situations where teamwork and discipline were necessary to complete school activities and assignments successfully. I have learned that group work becomes more effective when every member understands their responsibility and respects the contributions of others. My determination helps me continue working even when a task becomes difficult. I also try to be fair when working with classmates because I believe everyone deserves to be treated equally. Accountability is applicable because I understand that accepting responsibility helps build trust. If I become a student leader, these skills can help me organize activities, communicate with students, and coordinate with teachers. They can also help me handle disagreements calmly and focus on finding solutions instead of blaming other people.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('3f59e38b-b095-4aaa-aeff-48f3d7ab57f0', '5e59fd3c-3370-47f9-98db-7e6ae73c8664', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Fernandez', 'Hannah', 'Louise', null, 'Grade 9', 'Grade 9 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2011-04-25', 14, 'hannahfernandez@gmail.com', '09245551202', null, 'Purok 3 Brgy. Iraya Sur San Vicente, Camarines Norte', 'Marissa L. Fernandez', '09245551202', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_04ac60cf-b8a8-4e19-ac5c-862e25ed7fcb_1786890472161.jpg', '{"skills": ["Communication", "Problem Solving"], "qualities": "I believe compassion, accountability, confidence, teamwork, and willingness to learn can help me become a great leader. Compassion helps me understand the concerns of other students instead of immediately assuming that everyone has the same experiences. Accountability means accepting responsibility for decisions and being honest about mistakes. Confidence helps me communicate clearly and represent students during discussions. Teamwork reminds me that leadership is not about one person accomplishing everything alone. A leader needs the skills and ideas of other people. Willingness to learn allows me to improve when someone provides constructive criticism. I believe these qualities can help me become a leader who is approachable and dependable. My goal is to encourage students to participate and demonstrate that meaningful leadership comes from serving others rather than seeking personal recognition.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become an organization that students trust because it consistently listens, communicates, and acts on legitimate concerns. In three years, I want students to have more opportunities to participate in school governance and suggest projects that address their needs. The organization should promote academic development, student welfare, environmental responsibility, leadership training, and community involvement. I also want student leaders to use technology to make communication faster and more accessible while maintaining proper privacy and security practices. Programs should be documented and evaluated so future officers can learn from previous experiences. Most importantly, I want the Learner Government to create a culture of respect and cooperation where students, teachers, and administrators work together. Its primary goal should always be improving the student experience.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have learned that school activities become more successful when students cooperate and communicate effectively. Compassion allows me to understand different perspectives when classmates have concerns. Accountability helps me take responsibility for assignments and group responsibilities. Confidence allows me to share ideas during discussions while remaining open to other opinions. Teamwork helps me understand the importance of distributing responsibilities and recognizing the contributions of other people. My willingness to learn allows me to accept feedback without taking criticism personally. These qualities can be useful in the Learner Government because student leaders must communicate with different groups and make decisions that affect many students. I believe these skills can help me become a responsible representative who listens carefully, works cooperatively, and continuously seeks ways to improve.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('42be6873-b289-4edc-b1f5-1c4d2e70b5e2', '6431fc47-651e-429a-964b-ee25f422e0c5', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Cruz', 'Angela', 'Marie', null, 'Grade 11', 'Treasurer', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2010-02-18', 16, 'angelacruz@gmail.com', '09205550435', null, 'Purok 3 Brgy. Cagbalogo Vinzons, Camarines Norte', 'Jonathan M. Cruz', '09205550435', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_b5f5a836-572f-4e4f-af5a-b1722725b887_1786891661555.jpg', '{"skills": ["Goal-Oriented", "Values-Oriented", "Communication", "Problem Solving"], "qualities": "The qualities I believe can make me a great leader are empathy, responsibility, organization, confidence, and perseverance. Empathy allows me to understand that students may have different experiences and concerns. Responsibility helps me complete tasks and respect commitments made to others. Organization allows me to manage projects efficiently and make sure important details are not forgotten. Confidence helps me communicate ideas and represent students even when speaking in front of others can be challenging. Perseverance helps me continue working when problems arise. I believe these qualities become more valuable when combined with humility. A leader should recognize that other people may have better ideas and should be willing to accept suggestions. My goal is to lead through cooperation and encourage other students to believe that their contributions matter.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become a highly organized student organization that students can depend on. In three years, I hope there will be stronger communication between student representatives and the student body. Students should have accessible ways to submit concerns, suggestions, and feedback. I also want the organization to create programs that encourage students to develop leadership skills, participate in community activities, protect the environment, and support their classmates academically. The Learner Government should also make sure that projects are properly evaluated so future officers can improve them. I believe continuity is important because every new group of leaders should build upon the accomplishments of previous leaders. Ultimately, I want the Learner Government to become a responsible organization that promotes participation, cooperation, and positive change.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have learned how important communication and organization are when completing school activities. When working with classmates, I usually try to make sure that everyone understands what they are expected to do. I also believe listening is important because sometimes the best solution comes from an idea that another person shares. My empathy allows me to consider how decisions may affect different students. Organization helps me manage responsibilities and deadlines. Being willing to learn is useful because school environments constantly change and new challenges can appear. If I become part of the Learner Government, these skills can help me communicate with students, organize projects, work with teachers, and evaluate problems carefully before suggesting solutions.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('42c7c233-194a-44a9-ab9f-5b9d9c8f27a1', '92cb4168-e137-49d8-ac3f-0755d6d6feaf', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Herrera', 'Vincent', 'Aaron', null, 'Grade 10', 'Grade 10 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2011-05-13', 14, 'vincentherrera@gmail.com', '09905132011', null, 'Purok 3 Brgy. Gubat Daet, Camarines Norte', 'Michelle A. Herrera', '09905132011', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_39447952-11af-44d6-8d4c-6b930cf5b0fa_1786898221473.jpg', '{"skills": ["Motivational", "Values-Oriented"], "qualities": "I believe maturity, responsibility, initiative, empathy, communication, and problem-solving are qualities that can make me a great leader. Maturity helps me consider the consequences of decisions. Responsibility reminds me that accepting a leadership position means fulfilling duties consistently. Initiative encourages me to act when I notice something that could be improved. Empathy helps me understand different perspectives. Communication allows me to explain ideas and represent student concerns. Problem-solving helps me consider possible solutions rather than simply identifying problems. I believe a great leader should encourage others to participate and should remain accountable for their actions. I want to become a leader who focuses on practical improvements and meaningful service.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to support students academically, socially, and personally. In three years, I hope the organization provides more opportunities for leadership development, teamwork, communication, environmental responsibility, academic support, and community involvement. I want representatives to communicate regularly with students and use their feedback when planning activities. Programs should also be evaluated after implementation so future officers can improve them. I envision stronger cooperation between different grade levels and better communication with school personnel. Most importantly, students should see their Learner Government as an organization that listens and takes practical action. Student leadership should create opportunities for students to grow and contribute.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I have worked with classmates on academic projects and school activities where planning and cooperation were necessary. I understand the importance of sharing responsibilities and communicating expectations. My initiative helps me identify tasks that need attention, while problem-solving helps me consider possible approaches when challenges occur. As Grade 10 Representative, I would listen to classmates about academic concerns, activities, and other issues that affect their school experience. I would communicate these concerns to the Learner Government respectfully. I also want to encourage students to participate in leadership activities and programs that can help them develop skills beyond academics.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('46b354c1-a376-4686-9345-fa3f89c98389', '46cfd31f-e42b-4a9b-bffc-2ffe91af173f', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Reyes', 'Joshua', 'Carlo', null, 'Grade 11', 'Vice President', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2009-08-22', 16, 'carlo@gmail.com', '09827272737', null, 'Brgy. Bagong Silang I Labo, Camarines Norte', 'Laie A. Hena', '09973773733', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_9299e954-6949-45ac-8b4c-e557eaff9210_1786896681441.jpg', '{"skills": ["Values-Oriented"], "qualities": "As an inspiring student leader, I possess responsibility, determination, honesty, and compassion. I am willing to listen to others and understand their concerns before making decisions. I believe that a good leader should lead by example, remain respectful, and treat everyone fairly regardless of their differences. I am also committed to teamwork because I believe that great results are achieved when people work together. When challenges arise, I stay calm, learn from mistakes, and look for practical solutions. Most importantly, I am willing to serve, support, and encourage my fellow learners while continuously improving myself as a leader and as a person.", "makaTaoProject": "Jajsj", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Kajajl", "makabansaProject": "Ydjen", "skillsExplanation": "These skills are applicable to me because they reflect the qualities I need as a responsible and effective student leader. Communication helps me express ideas clearly and understand the concerns of my fellow learners. Leadership allows me to guide others, make responsible decisions, and encourage teamwork. Time management helps me balance my academic responsibilities with leadership duties. Problem-solving enables me to handle challenges calmly and find practical solutions. I also value adaptability because student organizations face different situations that require flexibility. Most importantly, these skills will help me serve others, build trust, promote cooperation, and contribute positively to our school community.", "makaTaoDescription": "Kskksak", "makaDiyosDescription": "Jajsjaj", "makabansaDescription": "Ekek", "makakalikasanProject": "Kwkksk", "makakalikasanDescription": "Kskskks"}', true, true, true, true, true, null, null, 'low'),
  ('4dab9d58-416b-4997-ad64-873e11231098', 'ba72095a-44aa-4d23-9615-39fee9f84139', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Rivera', 'Alexander', 'James', null, 'Grade 9', 'President', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2009-06-21', 16, 'alexanderrivera@gmail.com', '09905212009', null, 'Purok 1 Brgy. Camambugan Daet, Camarines Norte', 'Daniel J. Rivera', '09905212009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_bbc6b0d5-c70b-4fab-89bb-4d2c682741e4_1786896848079.jpg', '{"skills": ["Goal-Oriented", "Values-Oriented", "Motivational", "Problem Solving", "Communication", "Service-Oriented"], "qualities": "I believe integrity, responsibility, empathy, determination, communication, and humility can make me a great leader. Integrity allows me to remain honest even when making difficult decisions. Responsibility reminds me that accepting a position means accepting accountability for my actions. Empathy helps me understand that students have different experiences and concerns. Determination allows me to continue working toward goals even when progress is slow. Communication helps me listen to students and explain ideas clearly. I also believe humility is important because leaders should recognize that they do not know everything. A great leader should be willing to learn from others, accept constructive criticism, and improve. I want to lead by serving others rather than seeking recognition.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that is more organized, transparent, inclusive, and student-centered. I want students to feel that their representatives genuinely listen to their concerns and take appropriate action. I envision regular consultations where students can provide suggestions about academic programs, school activities, environmental projects, student welfare, and other concerns. I also want future officers to maintain proper documentation so successful projects can continue even when new leaders are elected. Technology can help improve communication and feedback collection, but personal interaction should remain important. My vision is for the Learner Government to become an organization that students trust because it consistently demonstrates responsibility, transparency, and genuine service.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have experience working with classmates during group activities, academic projects, and school programs. I have learned that good communication and cooperation are necessary when several people are working toward one goal. I also try to remain responsible when I am given an assignment or task because I understand that other people may depend on me. My determination helps me continue working when a project becomes difficult. Empathy allows me to consider the opinions and experiences of other students before making decisions. If elected, I would use these abilities to communicate with students, coordinate with officers, and help develop programs that respond to actual student needs rather than personal preferences.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('536100c4-30a5-4bc3-8160-676bf07fcc6a', '7f49c970-c0b8-4343-a214-d82a787245b0', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Ramos', 'Ethan', 'Mark', null, 'Grade 7', 'Grade 7 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2013-04-08', 12, 'ethan@gmail.com', '09826483649', null, 'Brgy. Dayhagan Jose Panganiban, Camarines Norte', 'Leo A. Ralfo', '09283837393', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_ba8b894e-edf4-45f3-bbcd-6aeb5e7f8db3_1786898352818.jpg', '{"skills": ["Motivational"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jsjsj", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Ksksks", "makabansaProject": "Jzjd", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Kskss", "makaDiyosDescription": "Ksksks", "makabansaDescription": "Jsks", "makakalikasanProject": "Jsjsj", "makakalikasanDescription": "Ksksks"}', true, true, true, true, true, null, null, 'low'),
  ('54874826-9296-4805-bbae-4cad7882ccfc', 'c18d5fc7-478c-4a63-a2c8-e1621ac07ef0', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Reyes', 'Miguel', 'Andres', null, 'Grade 11', 'President', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2010-03-14', 15, 'miguelreyes@gmail.com', '09175550148', null, 'Purok 2 Brgy. Calasgasan Daet, Camarines Norte', 'Maria A. Reyes', '09175550148', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_5cec4032-3a28-4740-94f4-c428905c72c7_1786889870563.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented", "Service-Oriented", "Communication", "Problem Solving"], "qualities": "I believe that my willingness to listen, responsibility, determination, adaptability, and respect for others can help me become a great leader. I understand that leadership comes with responsibilities and that decisions should consider the welfare of the people being represented. I am willing to listen to different opinions, including constructive criticism, because I believe that no leader has all the answers. I am also determined to continue working even when a project becomes difficult or does not immediately produce the expected results. Adaptability is important because situations in school can change, and leaders must be able to respond appropriately. Above all, I value respect because every student deserves to be treated fairly regardless of their background, academic performance, or personal opinions. I want to lead through actions rather than simply through promises.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government as a more organized, transparent, active, and student-centered organization where every learner has an opportunity to participate and express their concerns. I want the Learner Government to become a bridge between students, teachers, and school administrators rather than simply being an organization that conducts events. It should actively gather student feedback and use that information to create meaningful programs. I also envision a Learner Government that promotes academic support, leadership development, environmental responsibility, student welfare, and inclusive activities. Technology can also be used to improve communication, announcements, surveys, and student participation. Most importantly, I hope future student leaders will continue the projects of previous leaders while creating new solutions for emerging student concerns. The goal should be a responsible government that students can trust.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I regularly interact with different classmates and participate in group activities where cooperation and communication are necessary. When working with other students, I try to understand their opinions before giving my own suggestions. I believe that being responsible helps me complete tasks properly and encourages others to trust me. Communication is also important because a student leader needs to explain plans clearly and listen carefully to concerns from students, teachers, and school organizations. Patience helps me handle disagreements without immediately becoming frustrated, while honesty allows me to make decisions fairly. These skills can help me represent students effectively because they allow me to communicate their concerns, cooperate with others, and approach problems with a responsible and positive attitude.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('5b679be3-f016-4cc6-9f83-fb037b4d54dc', '8f1f79f4-5ab6-4ad9-bd30-b214a9a11f16', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Aquino', 'Nicole', 'Patricia', null, 'Grade 7', 'Grade 7 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2013-08-03', 12, 'nicoleaquino@gmail.com', '09235550980', null, 'Purok 1 Brgy. Bactas Basud, Camarines Norte', 'Manuel P. Aquino', '09235550980', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_21040e91-0bbd-4709-89be-9b7886ffff1c_1786890766407.jpg', '{"skills": ["Motivational", "Service-Oriented"], "qualities": "I believe empathy, optimism, creativity, responsibility, and communication can help me become a great leader. Empathy allows me to consider the experiences and concerns of other students. Optimism helps me encourage others when situations become difficult. Creativity allows me to think of new solutions and develop programs that students may find meaningful. Responsibility ensures that I take commitments seriously and remain accountable for my actions. Communication allows me to explain ideas clearly while also listening to criticism and suggestions. I believe these qualities should be combined with respect because every student deserves to be heard. A great leader should not make people feel that their opinions are unimportant. I want to become a leader who encourages students to participate, supports teamwork, and creates opportunities for everyone to contribute to the school community.", "makaTaoProject": "S", "threeYearVision": "My vision for the Learner Government in three years is an organization that creates a positive and inclusive environment for students. I want every learner to feel that their voice has value, regardless of their academic performance, interests, or level of involvement in school organizations. The Learner Government should create programs that support academic growth, mental and social well-being, environmental awareness, creativity, sports, and community service. I also want the organization to use technology responsibly to improve communication between leaders and students. Student feedback should be collected regularly and considered when planning projects. I hope future leaders will also establish clear documentation and evaluation systems so successful programs can continue. Ultimately, I want the Learner Government to help students become confident, responsible, creative, and socially aware young leaders.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I enjoy working with other students and participating in activities that require communication and creativity. I have learned that people respond differently to problems, so empathy helps me understand their perspectives. Optimism helps me remain motivated when tasks become difficult. My communication skills help me express suggestions while also listening to feedback. Creativity is useful when developing projects because familiar activities can sometimes be improved by introducing new ideas. Responsibility ensures that I do not forget the commitments I make to others. These qualities can help me contribute to the Learner Government because student leaders must plan activities, communicate with students and teachers, solve problems, and encourage participation. I believe these skills can help me become a responsible and approachable representative.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('626f9061-8430-431b-ab3d-741886a0243b', '6b7d5c2a-13fb-41c5-94a4-8ad47ce86bff', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Villanueva', 'Kevin', 'John', null, 'Grade 11', 'Grade 11 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2010-03-10', 16, 'kevin@gmail.com', '09938383838', null, 'Brgy. Pinagtigasan Vinzons, Camarines Norte', 'Us W. Ualeo', '09488484847', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_69e9f468-5e7b-4e52-b54b-983f664d8a20_1786897692482.jpg', '{"skills": ["Problem Solving"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Ghm", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Nj", "makabansaProject": "Jk", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Ng", "makaDiyosDescription": "Jh", "makabansaDescription": "Jwj", "makakalikasanProject": "K", "makakalikasanDescription": "K"}', true, true, true, true, true, null, null, 'low'),
  ('697b021d-952b-4dce-bc5c-83d5490eddb2', 'f3f0ccf5-a244-4ba5-b743-be621c79810c', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Garcia', 'Daniel', 'Luis', null, 'Grade 11', 'Treasurer', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Male', '2009-08-05', 16, 'daniel@gmail.com', '09973828478', null, 'Brgy. Larap Jose Panganiban, Camarines Norte', 'Karloff A. Hasu', '09927373838', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_090cf877-a3df-4e9e-a37a-73a78ea63a50_1786896944945.jpg', '{"skills": ["Motivational"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Kdkdk", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Ysnenc", "makabansaProject": "Kxjd", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Kdjndn", "makaDiyosDescription": "Jsksksk", "makabansaDescription": "Kdkks", "makakalikasanProject": "Jxjddn", "makakalikasanDescription": "Jdjdjksjfjkd"}', true, true, true, true, true, null, null, 'low'),
  ('76eece77-d160-4722-bd33-f255be5733ad', 'b13aebbd-8e10-45f6-9461-8388769684e0', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Santos', 'Maria', 'T', null, 'Grade 8', 'Vice President', 'c1286650-6274-4afa-a599-9eda53ce1f20', 'Female', '1999-02-01', 27, 'test2@gmail.com', '09922222222', null, 'Test 2 Brgy. Bibirao Daet, Camarines Norte', 'Test2 T. Est', '09922222222', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_a2815899-3e8c-41b8-bced-42b92a115deb_1786280187150.jpg', '{"skills": ["Values-Oriented", "Communication"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "T", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaDiyosProject": "T", "makabansaProject": "T", "skillsExplanation": "These skills are applicable to me because they reflect the way I approach both my academic responsibilities and my interactions with others. Whenever I am given a task, I make sure to complete it with dedication, organization, and attention to detail. I enjoy collaborating with classmates, sharing ideas, and finding solutions to problems through teamwork. I am also willing to step forward when leadership is needed while remaining humble enough to accept suggestions and learn from mistakes. I understand that leadership requires patience, responsibility, and effective communication, and I continuously work to improve these qualities. My experiences in school have taught me the importance of being reliable, respectful, and compassionate. These skills enable me to serve not only as a leader but also as someone who genuinely represents and supports the interests of every student.", "makaTaoDescription": "Est", "makaDiyosDescription": "Est", "makabansaDescription": "Est", "makakalikasanProject": "T", "makakalikasanDescription": "Est"}', true, true, true, true, true, null, null, 'low'),
  ('79cd50d7-e195-4ea7-90a2-3f4224934e6f', '89e5abfc-bd5b-420f-ab80-acd62f3c2c45', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Bautista', 'Chloe', 'Anne', null, 'Grade 8', 'Grade 8 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2012-06-10', 13, 'chloe@gmail.com', '09837393873', null, 'Brgy. Baay Labo, Camarines Norte', 'Sarko K. Uake', '09937383839', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_613409c5-0706-4251-9d4e-b4ee5d4e05fb_1786898256906.jpg', '{"skills": ["Service-Oriented"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jfjr", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Jgjjf", "makabansaProject": "Jrkrk", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Jrk", "makaDiyosDescription": "Jfir", "makabansaDescription": "Xjjxj", "makakalikasanProject": "Rjjr", "makakalikasanDescription": "Iii"}', true, true, true, true, true, null, null, 'low'),
  ('80138714-8e5a-498c-92b3-5c0cf8c3fd81', 'b41f63e3-909e-4d4a-8bfe-a3fc4b3dcb45', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Ramos', 'Ethan', 'Gabriel', null, 'Grade 10', 'Protocol Officer', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2010-12-09', 15, 'ethanramos@gmail.com', '09225550979', null, 'Purok 1 Brgy. Bagong Bayan Jose Panganiban, Camarines Norte', 'Teresa G. Ramos', '09225550879', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_da661475-eb73-4368-bca4-c8853bdcae5b_1786890893415.jpg', '{"skills": ["Goal-Oriented", "Communication", "Problem Solving"], "qualities": "Courage, adaptability, responsibility, fairness, and perseverance are qualities that I believe can help me become a great leader. Courage gives me the ability to address problems and communicate concerns even when doing so may be uncomfortable. Adaptability helps me respond to unexpected situations without losing focus. Responsibility reminds me that leadership is a commitment rather than simply a title. Fairness helps me avoid making decisions based on favoritism. Perseverance encourages me to continue pursuing goals even after encountering setbacks. I also believe that leaders should be willing to seek assistance when necessary. Asking for help does not mean weakness; it can demonstrate maturity and teamwork. I want to become a leader who remains dependable during both successful and difficult situations while encouraging others to contribute their talents.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that is more responsive to student concerns and capable of adapting to changing needs. I want it to become an organization where students can communicate their suggestions easily and where leaders provide regular updates about ongoing projects. I also envision stronger cooperation between the Learner Government, school organizations, teachers, and administrators. Programs should focus on student welfare, academic improvement, environmental responsibility, leadership training, and community involvement. I believe the organization should also develop proper transition procedures so incoming officers can learn from previous leaders and continue effective programs. My vision is not simply to have more activities but to have better activities with clear objectives and measurable results. The Learner Government should become a model of responsible and participatory student leadership.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because school activities often require students to adjust to unexpected situations. I have learned that even a well-planned activity can experience changes in schedules, responsibilities, or available resources. Adaptability allows me to remain calm and look for alternatives. Courage helps me communicate when something needs to be addressed, while fairness helps me consider different opinions. Responsibility ensures that I complete my assigned tasks and communicate if I encounter difficulties. Perseverance helps me continue working toward goals even when the first attempt does not succeed. These skills are important for student leadership because representatives must coordinate with different groups and respond to problems. I believe they can help me become a reliable member of the Learner Government.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('828a5066-e5c2-47d5-a4ab-785e4e914bff', '9f8ba920-d0a5-47a3-95f9-855a507eaa7b', 'f48e5ec2-4e96-4731-94b2-3ac0825edf0d', 'Navarro', 'Daniel', 'l', null, 'Grade 12', 'President', '7162ee76-5bb6-43c2-8126-917c0e2cc9e6', 'Male', '2001-11-07', 24, 'leo@gmail.com', '09987654321', null, 's, Baclayon, Bacacay, Albay, Region V', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_2bed254e-1239-4352-a48a-00f07f90202e_1778347202054.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented"], "qualities": "s", "threeYearVision": "s", "skillsExplanation": "s"}', true, true, true, true, true, null, null, 'low'),
  ('91500ae7-ae4c-481e-ad42-53206de3d64d', '99317581-671e-40e2-9b4b-1f8131f1ee13', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Villareal', 'Nathan', 'Carlo', null, 'Grade 11', 'Secretary', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2009-11-08', 16, 'nathanvillareal@gmail.com', '09911082009', null, 'Purok 1 Brgy. Bagasbas Daet, Camarines Norte', 'Joseph C. Villareal', '09911082009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_2d3fdacb-6de6-45a0-a9fe-7f6b1dc66f43_1786897196653.jpg', '{"skills": ["Values-Oriented", "Goal-Oriented", "Communication"], "qualities": "I believe reliability, organization, discipline, responsibility, attention to detail, and honesty can make me a great leader. Reliability means people can trust me to complete responsibilities on time. Organization helps me manage different tasks without losing important information. Discipline allows me to follow procedures and deadlines consistently. Responsibility reminds me that other students may depend on the work I do. Attention to detail helps prevent mistakes when handling documents or announcements. Honesty ensures that information I provide is accurate. I understand that some leadership responsibilities happen behind the scenes and may not receive recognition. I am willing to perform those responsibilities because I believe successful organizations depend on consistent preparation and reliable people.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government with an organized and reliable documentation system. Important meetings, decisions, programs, reports, and accomplishments should be properly recorded so future officers can understand the organization''s history. I also want communication between the Learner Government and students to become clearer and more consistent. Students should know about upcoming activities, changes, and important announcements without unnecessary confusion. Digital tools can be used to organize information, but proper procedures should still be followed. I believe documentation can help future officers avoid repeating mistakes and continue successful programs. My vision is an organization that values organization, transparency, continuity, and accurate communication.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I am comfortable organizing information and managing different tasks. During group projects, I often help classmates keep track of requirements and deadlines. I understand that missing a small detail can sometimes affect an entire project. My organizational skills would be especially useful as Secretary because the position requires accurate records and communication. If elected, I would make sure that meeting information, important decisions, schedules, and announcements are properly documented. I would also communicate information clearly to officers and representatives. Maintaining organized records would help current officers work efficiently and would also provide future student leaders with useful references when continuing existing programs.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('95dec67e-2e07-4907-8802-68b5b338c301', '963329d6-f8ed-4bc3-914b-2123b95d0930', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Marquez', 'Ethan', 'Lucas', null, 'Grade 8', 'Grade 8 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2012-07-07', 13, 'ethanmarquez@gmail.com', '09907072012', null, 'Purok 3 Brgy. Camambugan Daet, Camarines Norte', 'Jennifer L. Marquez', '09907072012', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_3b2cd77c-c05b-4475-8d76-2b71c9ef0b7d_1786898037985.jpg', '{"skills": ["Values-Oriented", "Motivational"], "qualities": "I believe confidence, empathy, creativity, teamwork, responsibility, and determination can make me a great leader. Confidence helps me speak when student concerns need representation. Empathy reminds me to listen before making decisions. Creativity allows me to consider new solutions. Teamwork helps me recognize the contributions of other people. Responsibility keeps me committed to my duties, while determination helps me continue working when challenges arise. I believe leaders should also be humble and willing to recognize when someone else has a better idea. My goal is to become a leader who encourages students to participate, listens to their concerns, and creates opportunities for them to contribute their own abilities.", "makaTaoProject": "S", "threeYearVision": "My vision is for the Learner Government to become a more inclusive and collaborative organization. In three years, I hope representatives regularly ask students what activities they actually want instead of making decisions without consultation. I want the organization to provide opportunities in academics, sports, arts, environmental projects, leadership, and community service. Different students have different interests, so there should be many ways to participate. I also want technology to be used responsibly for feedback and communication. However, personal interaction should remain important. My vision is for students to feel that the Learner Government belongs to them and that their participation can directly contribute to improving their school environment.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I enjoy participating in group activities and working with classmates. I have learned that teamwork requires people to communicate clearly and respect different strengths. I also try to understand different opinions before making decisions. As Grade 8 Representative, I would listen to my classmates and communicate their concerns to the Learner Government. I would encourage students to participate in activities and share suggestions for future programs. My creativity could help develop activities that are both educational and enjoyable. Responsibility would ensure that I follow through with commitments. I want to become a representative who students can trust to listen to them and communicate their ideas properly.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('9886abdc-544a-4062-a5dc-4f0152704658', 'f68b1392-c08c-403f-b503-3aeed894009b', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Garcia', 'Joshua', 'Miguel', null, 'Grade 8', 'Auditor', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2009-09-30', 16, 'joshuagarcia@gmail.com', '09195550546', null, 'Purok 4 Brgy. Del Rosario Mercedes, Camarines Norte', 'Patricia M. Garcia', '09195550546', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_45e6383e-d112-48ba-a03c-00e1c284e7ec_1786891280901.jpg', '{"skills": ["Service-Oriented", "Communication", "Values-Oriented", "Goal-Oriented"], "qualities": "My confidence, resilience, responsibility, respect, and teamwork are qualities that I believe can help me become a great leader. Confidence gives me the courage to communicate concerns and propose ideas. Resilience allows me to continue working when a project experiences difficulties. Responsibility reminds me that leadership involves commitments that should be taken seriously. Respect helps me treat different opinions fairly, even when I disagree with them. Teamwork helps me recognize that successful projects require the contributions of many people. I also believe a great leader should be willing to admit mistakes and improve. Leadership should not be measured only by the number of activities completed but also by the positive impact those activities have on students. I want to become a leader who encourages participation and creates opportunities for others.", "makaTaoProject": "S", "threeYearVision": "I envision a Learner Government that is known for being active, transparent, innovative, and dependable. In three years, I hope student representatives will regularly communicate with learners instead of only approaching them during elections or major events. I want students to have opportunities to suggest projects and participate in decision-making activities. The organization should also promote programs that support student welfare, academic development, environmental responsibility, and leadership. Technology can be used to improve announcements, surveys, and feedback collection. I also envision better cooperation between different student organizations so that programs do not overlap unnecessarily and resources can be used effectively. Most importantly, I want the Learner Government to develop a culture where leaders understand that their position is temporary but their responsibility to serve the student body should remain a priority.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have learned to cooperate with different classmates during projects and school activities. Not everyone approaches tasks in the same way, so understanding different working styles is important. Confidence helps me share ideas, while respect allows me to listen when someone disagrees with me. Resilience is useful when projects encounter problems because difficulties should not automatically mean that a goal should be abandoned. Responsibility helps me make sure that assigned tasks are completed properly. I believe these qualities will be useful in the Learner Government because student leaders must coordinate with many people and deal with different opinions. These skills can help me remain focused on solutions while maintaining positive relationships with other students and members of the school community.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('b6873067-d0b8-469a-a062-c476ae77c780', 'e4418420-07cb-4279-8552-11d2719e0c43', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Mendoza', 'Sofia', 'Anne', null, 'Grade 10', 'Vice President', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Female', '2010-07-22', 15, 'sofiamendoza@gmail.com', '09175550213', null, 'Purok 6 Brgy. Bibirao Daet, Camarines Norte', 'Roberto A. Mendoza', '09175550213', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_86901abe-6c6f-49ff-823f-efa45dcd5c7d_1786891946514.jpg', '{"skills": ["Goal-Oriented", "Service-Oriented", "Communication", "Problem Solving"], "qualities": "I believe my determination, honesty, patience, willingness to listen, and ability to cooperate with others can help me become a great leader. I understand that leadership involves difficult decisions and responsibilities, so I am willing to learn from experiences and accept constructive criticism. I also believe honesty is important because students deserve representatives who communicate information truthfully and do not make promises they cannot fulfill. My willingness to listen can help me understand problems from different perspectives before making decisions. I also value teamwork because no leader can accomplish meaningful goals alone. A successful student government requires students, teachers, and school leaders to cooperate. I want to become the kind of leader who encourages others, respects different opinions, and continues working even when challenges make a goal difficult to achieve.", "makaTaoProject": "S", "threeYearVision": "My vision for the Learner Government in three years is to have an organization that is more accessible, transparent, active, and responsive to students. I want students to know that they can approach their representatives when they have suggestions, concerns, or ideas for improving school life. The Learner Government should organize programs that address academic needs, student welfare, leadership development, environmental awareness, and community involvement. I also want future leaders to use technology to communicate announcements and gather student feedback more efficiently. The organization should regularly evaluate its programs instead of simply completing activities for compliance. In three years, I hope the Learner Government will be recognized as a trusted organization that genuinely represents students and works together with teachers and administrators to create a safe, supportive, and productive learning environment.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I often work with classmates during group activities, school projects, and different classroom responsibilities. I have learned that cooperation becomes easier when everyone is given an opportunity to speak and contribute. My communication skills help me explain ideas clearly, while patience helps me understand people who may have different opinions from mine. Responsibility is also important because students and teachers need to trust their representatives to complete tasks properly. I also consider compassion an important skill because students may experience problems that are not immediately visible to others. Being able to listen and understand their situations can help me become a better representative. These qualities will allow me to work effectively with both students and teachers while remaining focused on the needs of our school community.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('b6f680d6-1621-4e8b-8e7b-c3137e25603d', '543eb220-5a23-493e-9b2c-48c8ce4e134f', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Rafon', 'Sofia', 'Mae', null, 'Grade 12', 'Auditor', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2009-05-18', 16, 'sofia@gmail.com', '09973737373', null, 'Brgy. Maisog San Lorenzo Ruiz, Camarines Norte', 'Haur A. Laso', '09928374844', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_725ac484-1dee-4a7a-aac9-3c0dc15f267c_1786897094072.jpg', '{"skills": ["Values-Oriented"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jdjd", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Hsns", "makabansaProject": "Jdjdj", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Mxkdkd", "makaDiyosDescription": "Nsndns", "makabansaDescription": "Kdk", "makakalikasanProject": "Jdkdkd", "makakalikasanDescription": "Mdkjd"}', true, true, true, true, true, null, null, 'low'),
  ('ba9967bc-b68e-4023-a205-93cd18240ab6', 'f35309ec-0554-4f97-923d-da9e68072251', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Cruz', 'Maria', 'Angela', null, 'Grade 12', 'Secretary', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2009-08-09', 16, 'maria@gmail.com', '09972772772', null, 'Brgy. Bibirao Daet, Camarines Norte', 'Llasu J. Hado', '09827738383', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_9adfa1f7-137b-4a10-80c2-14e74c7e0504_1786896807487.jpg', '{"skills": ["Communication"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Kdkk", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Jans", "makabansaProject": "Jdjdd", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Iwusjjs", "makaDiyosDescription": "Jdjk", "makabansaDescription": "Jdkdkks", "makakalikasanProject": "Kskksks", "makakalikasanDescription": "Uddnn"}', true, true, true, true, true, null, null, 'low'),
  ('c8164da9-df80-4824-9415-77b36bf88c60', '4252a27a-1747-40a2-86fb-2beebe259613', 'bcbd2549-28a5-4f94-bf63-1035b77c61ba', 'Frog', 'Swamp', 'F', null, 'Grade 12', 'President', null, 'Male', '2001-05-05', 24, 'frog@gmail.com', '09222222222', null, '1 Brgy. Daculang Bolo San Lorenzo Ruiz, Camarines Norte', 'FR O. G', '09333333333', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_432bd6a6-b6ed-4b9f-bea1-79a246ff2a3b_1778590278040.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented"], "qualities": "F", "threeYearVision": "G", "skillsExplanation": "R"}', true, false, false, false, false, null, null, 'low'),
  ('c973256b-31e6-451b-8f16-55b284de192f', '72e3c9cb-aa97-4914-a66e-41fe6e852bd6', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Santiago', 'Ella', 'Beatrice', null, 'Grade 9', 'PRO', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2012-04-10', 13, 'ellasantiago@gmail.com', '09904102010', null, 'Purok 1 Brgy. Bagasbas Daet, Camarines Norte', 'Manuel B. Santiago', '09904102010', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_d9c5ee18-9899-4fb4-93fc-0438f31973dd_1786897520236.jpg', '{"skills": ["Motivational", "Values-Oriented"], "qualities": "My creativity, confidence, communication skills, responsibility, adaptability, and enthusiasm are qualities that can make me a great leader. Creativity allows me to think of different ways to solve problems and communicate information. Confidence helps me speak when students need someone to represent their concerns. Communication allows me to listen as well as explain ideas. Responsibility reminds me to verify information and complete my duties properly. Adaptability helps me respond when plans or circumstances change. Enthusiasm allows me to encourage other students to participate. I believe a great leader should make other people feel included and informed. I want to use my communication skills to encourage more students to become active members of the school community.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government with a clear, reliable, and student-friendly communication system. Students should be able to easily access information about activities, deadlines, programs, and opportunities. I believe digital platforms can be useful for announcements and feedback, but traditional communication should also remain available. The Learner Government should communicate in both directions. It should not only tell students what is happening but also listen to their concerns and suggestions. I hope future officers will understand the importance of responsible information sharing. My vision is for students to feel informed and connected to their representatives, resulting in stronger participation and greater trust in the Learner Government.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I enjoy presentations, communication activities, and creating ideas for school projects. I am comfortable explaining information to classmates and working with others to develop creative concepts. As PIO, I would help communicate important information about Learner Government activities, programs, and announcements. I would make sure that information is accurate before sharing it. I would also encourage students to ask questions and provide feedback. Creativity could help make campaigns more engaging, while responsibility would prevent the spread of incomplete or incorrect information. I believe my communication skills would help create a stronger connection between student representatives and the students they serve.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('d38c51fd-979c-44f2-8832-deb09db00b16', '5f66946e-7e23-481d-82ed-0fbda203a0f8', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Lorenzo', 'Saen', 'Patrick', null, 'Grade 10', 'Protocol Officer', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2010-12-05', 15, 'seanlorenzo@gmail.com', '09912052010', null, 'Purok 2 Brgy. Bibirao Daet, Camarines Norte', 'Eduardo P. Lorenzo', '09912052010', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_3796c0d0-5a2c-4247-a06c-e114f0746343_1786897836027.jpg', '{"skills": ["Values-Oriented", "Communication", "Service-Oriented"], "qualities": "My discipline, punctuality, organization, preparedness, professionalism, and respect can make me a great leader. Discipline helps me stay focused even when responsibilities become difficult. Punctuality demonstrates respect for the schedules of other people. Organization helps me manage different tasks and details. Preparedness allows me to anticipate possible challenges. Professionalism reminds me that student leaders represent more than themselves. Respect helps me maintain positive relationships with other students and school personnel. I believe a great leader should be dependable and consistent. I want people to know that they can rely on me to prepare properly, follow through with responsibilities, and remain calm when unexpected problems occur.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that is recognized for organized, professional, and well-planned activities. I want future officers to have clear procedures for meetings, ceremonies, programs, and other events. Responsibilities should be assigned early, schedules should be communicated clearly, and officers should know what is expected from them. I also hope future student leaders receive training in event management and professional conduct. Better organization can reduce confusion and allow students to focus on participating in activities. My vision is for the Learner Government to show that students can conduct successful programs while maintaining proper discipline, respect, and cooperation with school personnel.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I enjoy organizing tasks and preparing for activities before they begin. I like checking schedules, requirements, and responsibilities so that problems can be identified early. School events often involve many people, so coordination is necessary to avoid confusion. As Protocol Officer, I would work with other officers to make sure everyone understands their responsibilities during meetings and activities. I would also help ensure that proper procedures are followed. If unexpected situations occur, I would remain calm and look for practical alternatives. I believe my organization and preparedness can help the Learner Government conduct activities in a more orderly and professional manner.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('d5c790cf-b639-4a5e-b178-b2b19086ff8a', 'aee55d7b-bc74-4040-b2c4-3f1cd7904a35', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Aquino', 'Joshua', 'T', null, 'Grade 7', 'President', 'c1286650-6274-4afa-a599-9eda53ce1f20', 'Male', '1999-11-01', 26, 'test1@gmail.com', '09900000001', null, 'Caba Brgy. Cabayugan Cawayan, Masbate', 'Test1 T. Est', '09900000001', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_7db5dbf3-5a87-471d-b04d-55a6cf17a4de_1783442081411.jpg', '{"skills": ["Values-Oriented", "Communication", "Problem Solving"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "Test", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaDiyosProject": "Test", "makabansaProject": "Test", "skillsExplanation": "These skills are applicable to me because they reflect the way I approach both my academic responsibilities and my interactions with others. Whenever I am given a task, I make sure to complete it with dedication, organization, and attention to detail. I enjoy collaborating with classmates, sharing ideas, and finding solutions to problems through teamwork. I am also willing to step forward when leadership is needed while remaining humble enough to accept suggestions and learn from mistakes. I understand that leadership requires patience, responsibility, and effective communication, and I continuously work to improve these qualities. My experiences in school have taught me the importance of being reliable, respectful, and compassionate. These skills enable me to serve not only as a leader but also as someone who genuinely represents and supports the interests of every student.", "makaTaoDescription": "Test", "makaDiyosDescription": "Test", "makabansaDescription": "Test", "makakalikasanProject": "Test", "makakalikasanDescription": "Test"}', true, true, true, true, true, null, null, 'low'),
  ('d6dddb21-2913-4232-93c7-3762fe4edc8c', 'fe2d743d-c465-4bf5-9ad7-d66bb346f13d', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Flores', 'Adrien', 'Miguel', null, 'Grade 11', 'President', null, 'Male', '2009-05-24', 16, 'adrienflores@gmail.com', '09924052009', null, 'Purok 2 Brgy. Barangay II (Pob.) Daet, Camarines Norte', 'Marissa M. Flores', '09924052009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_87606c2f-53ad-4195-b3e3-dfeb10b8b626_1786899001445.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented", "Communication", "Service-Oriented", "Problem Solving"], "qualities": "My perseverance, accountability, initiative, adaptability, fairness, teamwork, and commitment to service are qualities that I believe can make me a great leader. Perseverance helps me continue working when challenges arise. Accountability means I am willing to accept responsibility for my decisions and correct mistakes when necessary. Initiative encourages me to take action instead of waiting for someone else to solve every problem. Adaptability allows me to adjust when circumstances change. Fairness helps me consider different perspectives before making decisions. Teamwork reminds me that leadership is a collective effort rather than an individual achievement. Most importantly, I believe service should be at the center of leadership. As an independent candidate, I want to prove that a leader can work with different groups while remaining focused on the interests of the students.", "makaTaoProject": "S", "threeYearVision": "My vision for the Learner Government three years from now is an organization that is student-centered, accountable, active, and sustainable. I want student leaders to develop programs based on actual student needs rather than simply organizing activities because they are traditional. I envision regular consultations, transparent reporting, academic support initiatives, environmental projects, leadership training, and opportunities for students to participate in community service. I also want successful projects to continue across different administrations. Every administration should document its programs, challenges, and recommendations so future leaders can improve upon previous work. I believe the Learner Government should become a place where students learn practical leadership through real responsibilities. My goal is to help create an organization where students feel represented regardless of their grade level, background, interests, or personal connections.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I have experienced situations where completing a project required planning, cooperation, and the ability to adjust when unexpected problems appeared. I try to take initiative when I see something that needs to be completed rather than waiting for someone else to do it. I also understand the importance of accepting responsibility for mistakes instead of blaming others. Teamwork has taught me that people have different strengths, and successful projects often happen when those strengths are combined. As an independent candidate, I believe these skills are especially important because I would need to work with officers and students from different backgrounds and perspectives. If elected, I would focus on cooperation rather than political divisions and would encourage every student to participate in the Learner Government.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('d9902677-4e3e-4a7d-933f-5403108be985', '10dbd98e-8ddc-444a-aa7a-f81bb6490575', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Herrera', 'Nicole', 'Faith', null, 'Grade 12', 'Grade 12 Representative', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2009-07-07', 16, 'nicole@gmail.com', '09937479283', null, 'Brgy. Barangay V (Pob.) Mercedes, Camarines Norte', 'Karlo A. Herrera', '09936397294', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_c605f8b6-b4ea-408a-8277-6eaf7c67fd76_1786898064715.jpg', '{"skills": ["Problem Solving"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jfidk", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Jfidk", "makabansaProject": "Jdk", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Idkdk", "makaDiyosDescription": "Iddk", "makabansaDescription": "Iejn", "makakalikasanProject": "Jdirk", "makakalikasanDescription": "Kdkrk"}', true, true, true, true, true, null, null, 'low'),
  ('dfc1cfd2-1707-4b97-9c06-a9f8662eae01', 'd60c388f-0f5c-4a5e-a063-6d12d79589f1', 'bcbd2549-28a5-4f94-bf63-1035b77c61ba', 'mario', 'mario', 'M', null, 'Grade 12', 'President', null, 'Male', '2001-11-01', 24, 'mario@gmail.com', '0987654321', null, 'Puro, Salvacion, Jose Panganiban, Camarines Norte, Region V', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_e2898ec3-e837-41e2-bc29-86aed32200e1_1778507946977.jpg', '{"skills": ["Motivational", "Values-Oriented", "Goal-Oriented"], "qualities": "Cle", "threeYearVision": "Cle", "skillsExplanation": "Cle"}', true, true, true, true, true, 'Incomplete Documents; Unclear/Unacceptable Introduction Profile', null, 'low'),
  ('dfd546d8-309f-4c4c-b352-3496eb75d4e4', '6896c7e2-77a4-40c2-8557-6ea9ee53ae05', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Bautista', 'Mark', 'Z', null, 'Grade 12', 'Vice President', '8a513434-048e-4235-85a4-a259389df184', 'Male', '2003-02-01', 23, 'Vinz@gmail.com', '09123444455', null, 'puro puro Brgy. Anislag Daraga, Albay', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_9133ac87-6b48-4a1c-bc98-72f33b1e15c8_1782803226295.jpg', '{"skills": ["Values-Oriented", "Service-Oriented", "Problem Solving", "Communication"], "qualities": "I believe an inspiring student leader should be responsible, approachable, respectful, and committed to serving others. I possess these qualities because I always strive to lead by example instead of simply giving instructions. I value teamwork and understand that every student''s opinion deserves to be heard and respected. I am willing to listen to concerns, accept constructive criticism, and make decisions that benefit the majority while remaining fair to everyone. I also stay positive during challenges and encourage others to work together toward a common goal. Rather than seeking recognition, I believe leadership is about service, integrity, and accountability. By being dependable, open-minded, and dedicated, I hope to inspire my fellow students to actively participate, cooperate, and contribute to creating a stronger and more united school community.", "makaTaoProject": "c", "threeYearVision": "In three years, I envision the Learner Government becoming a more active, transparent, and student-centered organization that truly represents the voices of every learner. I hope to see a government that encourages greater student participation in school activities, decision-making, and community projects while promoting unity, inclusivity, and respect among all students. Through effective leadership and collaboration with teachers and school administrators, I believe the Learner Government can implement meaningful programs that support students'' academic growth, mental well-being, leadership development, and extracurricular interests. I also envision stronger communication between students and school officials through regular consultations and feedback systems. Ultimately, I want the Learner Government to be recognized as an organization that inspires trust, promotes positive change, and empowers every student to become responsible, confident, and engaged members of the school community.", "makaDiyosProject": "a", "makabansaProject": "g", "skillsExplanation": "These skills are applicable to me because they reflect the way I approach both my academic responsibilities and my interactions with others. Whenever I am given a task, I make sure to complete it with dedication, organization, and attention to detail. I enjoy collaborating with classmates, sharing ideas, and finding solutions to problems through teamwork. I am also willing to step forward when leadership is needed while remaining humble enough to accept suggestions and learn from mistakes. I understand that leadership requires patience, responsibility, and effective communication, and I continuously work to improve these qualities. My experiences in school have taught me the importance of being reliable, respectful, and compassionate. These skills enable me to serve not only as a leader but also as someone who genuinely represents and supports the interests of every student.", "makaTaoDescription": "d", "makaDiyosDescription": "b", "makabansaDescription": "h", "makakalikasanProject": "e", "makakalikasanDescription": "f"}', true, true, true, true, true, null, null, 'low'),
  ('e69ad678-d93a-4c9c-b267-b3deb6a77f92', '02d03fca-d107-4ebc-a19d-f0dca72c341a', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Gomez', 'Patricia', 'Louise', null, 'Grade 8', 'Treasurer', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2010-01-26', 16, 'patriciagomez@gmail.com', '09901262010', null, 'Purok 3 Brgy. Awitan Daet, Camarines Norte', 'Renato L. Gomez', '09901262010', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_7e94da33-6c84-4a68-8bbf-5c9eda3347a4_1786897305373.jpg', '{"skills": ["Goal-Oriented", "Values-Oriented", "Service-Oriented"], "qualities": "I believe honesty, accountability, discipline, organization, fairness, and responsibility can make me a great leader. Honesty builds trust, while accountability means accepting responsibility for decisions. Discipline helps me follow established procedures even when doing so requires extra effort. Organization allows me to manage information and responsibilities effectively. Fairness helps me make decisions based on the needs of students rather than personal relationships. Responsibility reminds me that leadership is about service. I want students to feel confident that their representatives are trustworthy. A great leader should be willing to explain decisions, accept constructive criticism, correct mistakes, and continuously improve. These are principles I want to apply throughout my leadership experience.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that is known for transparency and responsible resource management. I want officers to plan activities according to clear objectives and realistic budgets. Resources should be prioritized for programs that provide meaningful benefits to students rather than being spent without a clear purpose. I also want proper documentation to become a normal part of every project. Future officers should be able to review previous budgets and learn from past experiences. I believe students should also understand the importance of accountability. A Learner Government that manages resources responsibly can build stronger trust with students, teachers, administrators, and the wider school community.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('e81a31bf-aeef-4881-bfc9-6aa7ae5b7e32', '72599a9a-e252-40d6-967d-4c9faaadbe4c', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Navarro', 'Isabella', 'Grace', null, 'Grade 12', 'PRO', 'cf93039f-3a77-4710-a60e-cbf33ed97cff', 'Female', '2009-02-12', 17, 'isabella@gmail.com', '09982738383', null, 'Brgy. Capacuan Paracale, Camarines Norte', 'Lari D. Navarro', '09983737373', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_4bdeb75f-b2cc-4b96-9f52-8542f1a70844_1786897451612.jpg', '{"skills": ["Problem Solving", "Values-Oriented"], "qualities": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoProject": "Jsk", "threeYearVision": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaDiyosProject": "Usks", "makabansaProject": "Kdj", "skillsExplanation": "In three years, I envision the Learner Government as an active, trusted, and inclusive organization that genuinely represents every learner. It should become a platform where students can freely share their concerns, ideas, and suggestions without hesitation. I envision leaders who are responsible, transparent, approachable, and committed to serving rather than simply holding positions. The Learner Government should organize meaningful programs that support students academically, socially, and personally while promoting unity and respect. Through strong communication, teamwork, and student participation, I hope it will become a model organization that empowers learners to become responsible leaders and active members of society.", "makaTaoDescription": "Jqocn", "makaDiyosDescription": "Kdk.", "makabansaDescription": "Isksk", "makakalikasanProject": "Ifne", "makakalikasanDescription": "N sk"}', true, true, true, true, true, null, null, 'low'),
  ('ee0fb3ba-8a46-46f7-9c4c-e53f97e22171', '4c6c0d5a-762b-4b6f-bb0e-20c7e88eac9c', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Torres', 'Adrian', 'Luis', null, 'Grade 10', 'Grade 10 Representative', 'e6b25626-b06b-462c-bfbf-0bc4287058d6', 'Male', '2010-06-12', 15, 'adriantorres@gmail.com', '09175551323', null, 'Purok 3 Brgy. Alawihao Daet, Camarines Norte', 'Elena L. Torres', '09175551323', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_a854cef3-ebe5-4efe-8661-09be9cf16174_1786890357801.jpg', '{"skills": ["Motivational", "Communication", "Service-Oriented"], "qualities": "I believe responsibility, confidence, teamwork, patience, and determination can help me become a great leader. Responsibility allows me to take commitments seriously and understand the effects of my decisions. Confidence gives me the courage to communicate ideas and represent student concerns. Teamwork reminds me that important goals cannot be accomplished by one person alone. Patience helps me listen to different opinions and handle disagreements respectfully. Determination allows me to continue working even when a project encounters difficulties. I also believe that a great leader should be willing to admit mistakes and learn from them. Leadership should not be about being the most powerful person in a group. Instead, it should be about helping others, creating opportunities for participation, and working toward improvements that benefit the entire student community.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision the Learner Government as a more organized, transparent, and student-centered organization. I want students to have more opportunities to communicate their concerns and suggestions directly to their representatives. The Learner Government should focus on programs that improve academic support, student welfare, environmental awareness, leadership development, and community participation. I also believe technology can help improve communication through online announcements, surveys, and feedback systems. Future leaders should document projects properly so successful programs can continue even after a new set of officers is elected. I hope the Learner Government will become an organization that students trust because it consistently communicates with them and acts responsibly. Most importantly, I want it to develop students who understand that leadership is about service, accountability, and cooperation.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable to me because I regularly participate in group activities where communication, cooperation, and responsibility are important. When working with classmates, I try to complete my assigned tasks and help others when necessary. I have learned that successful teamwork requires people to listen to one another and respect different opinions. My patience allows me to handle disagreements without immediately becoming frustrated, while determination helps me continue working when a project becomes difficult. Confidence allows me to communicate ideas and participate in discussions. These qualities would be useful in the Learner Government because student leaders must communicate with students, teachers, and other organizations. I believe these skills can help me become a dependable representative who listens to concerns and works with others to find practical solutions.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('ef1a770c-f91b-45df-be85-d36fd55d8fd6', '4884cecf-558c-43d7-97bf-346d8efba29a', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Gutierrez', 'Amelia', 'Rose', null, 'Grade 7', 'Grade 7 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2013-02-18', 13, 'ameliagutierrez@gmail.com', '09902132013', null, 'Purok 1 Brgy. Borabod Daet, Camarines Norte', 'Carlo R. Gutierrez', '09902182013', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_65d51991-35dc-46b1-9ac0-9a6ccc678d06_1786897939851.jpg', '{"skills": ["Values-Oriented", "Service-Oriented", "Communication"], "qualities": "My enthusiasm, friendliness, responsibility, cooperation, curiosity, and willingness to learn can help me become a great leader. I understand that I am still developing my leadership skills, but I believe being willing to learn is an important strength. Friendliness can help classmates feel comfortable sharing concerns. Responsibility reminds me to take my position seriously. Cooperation helps me work with other representatives and officers. Curiosity encourages me to ask questions and understand problems better. I believe a great leader does not have to be perfect. Instead, they should be willing to learn from mistakes, accept advice, and encourage others. I want to grow as a leader while helping my classmates grow with me.", "makaTaoProject": "S", "threeYearVision": "In three years, I hope the Learner Government becomes an organization where students from all grade levels feel included. I want younger students to understand that their opinions matter even if they are new to high school. I envision activities that bring different grade levels together through sports, academic competitions, environmental programs, leadership activities, and community projects. I also hope representatives communicate regularly with their classmates. Students should understand that they are not simply people who attend activities but are also members of the school community who can contribute ideas. My vision is for the Learner Government to help students develop confidence, responsibility, teamwork, and leadership skills from an early stage.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because I enjoy working with classmates and participating in activities. I try to listen when others have ideas and encourage students who may feel shy about participating. Responsibility is important because a representative needs to communicate information accurately and complete assigned tasks. My willingness to learn will help me understand student leadership better and improve my abilities. As Grade 7 Representative, I would listen to my classmates and communicate their concerns to the Learner Government. I would also encourage students to join school programs and activities. I believe participation can help students develop confidence, teamwork, friendships, and a stronger sense of responsibility.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('f4ba4cc6-850c-4f52-9028-601fd14364f1', '9e3a9172-b062-4a60-988e-eb991ae9f023', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Castillo', 'Dominic', 'Rafael', null, 'Grade 12', 'Grade 12 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Male', '2009-03-09', 17, 'dominiccastillo@gmail.com', '09903092009', null, 'Purok 7 Brgy. Itomang Talisay, Camarines Norte', 'Elena R. Castillo', '09903092009', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_ff708111-0c49-4623-9995-622e17e4d734_1786896966262.jpg', '{"skills": ["Goal-Oriented", "Communication"], "qualities": "I believe integrity, maturity, responsibility, empathy, confidence, communication, and perseverance can make me a great leader. Integrity allows me to remain honest even when decisions are difficult. Maturity helps me consider long-term consequences instead of focusing only on immediate results. Responsibility ensures that I take my commitments seriously. Empathy allows me to understand different student perspectives. Confidence helps me represent students appropriately, while communication allows me to listen and explain information clearly. Perseverance helps me continue working when challenges occur. I also believe great leaders should prepare the next generation of leaders. As a Grade 12 Representative, I want to leave behind positive examples and useful practices that future students can continue improving.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that has a strong culture of service, accountability, and continuity. I want each group of officers to build upon successful programs from previous years rather than starting over every election cycle. I envision proper documentation, regular consultations, leadership development, academic support, environmental programs, community service, and activities that encourage student participation. Programs should have clear objectives and evaluation methods so future officers can understand what worked and what needs improvement. Most importantly, the organization should remain student-centered. Its primary purpose should be to represent students, provide meaningful opportunities for participation, develop responsible leaders, and contribute positively to the school community.", "makaDiyosProject": "T", "makabansaProject": "G", "skillsExplanation": "These skills are applicable because my experiences throughout high school have taught me the importance of responsibility, communication, cooperation, and long-term planning. As students approach graduation, they may have different concerns and future plans. I believe a representative needs to listen carefully rather than assume everyone has the same priorities. I would use communication to gather feedback from my classmates and present their concerns respectfully. Maturity would help me approach difficult situations calmly, while responsibility would ensure that I follow through with commitments. I also want to encourage younger students to participate in leadership because student organizations become stronger when experienced students help prepare the next generation of representatives.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low'),
  ('fbc42cbe-c6a0-48ef-bbe8-2478017c99b8', '5e21f0c1-3e1b-413b-ba60-ea5c7ab90a51', '67ea45df-a0c0-4fc1-9843-0529ce6266ab', 'Fernandez', 'Julia', 'Mae', null, 'Grade 11', 'Grade 11 Representative', 'a7621ec7-a3fe-4a01-99cc-e19ae3113a2d', 'Female', '2010-12-01', 15, 'juliafernandez@gmail.com', '09912012010', null, 'Purok 3 Brgy. Mancruz Daet, Camarines Norte', 'Antonio M. Fernandez', '09912012010', 'https://hfeozvpwfxbdjhuhhkjg.supabase.co/storage/v1/object/public/candidate-pictures/candidate_2409dcd1-d0a5-4eca-8fe0-e7eb7a982658_1786898316265.jpg', '{"skills": ["Values-Oriented", "Service-Oriented", "Communication", "Goal-Oriented"], "qualities": "My maturity, empathy, critical thinking, responsibility, communication, and perseverance can make me a great leader. Maturity allows me to approach difficult situations carefully. Empathy helps me understand that students may have different experiences. Critical thinking allows me to evaluate information before making decisions. Responsibility ensures that I complete my duties. Communication allows me to represent student concerns accurately. Perseverance helps me continue working when progress is slow. I also believe leaders should be willing to learn from mistakes and accept feedback. I want to develop a leadership style based on listening, thoughtful decision-making, and service. My goal is to represent Grade 11 students fairly while helping strengthen the entire school community.", "makaTaoProject": "S", "threeYearVision": "In three years, I envision a Learner Government that helps students develop skills they can use beyond high school. I want the organization to provide leadership opportunities that teach communication, teamwork, decision-making, responsibility, and community service. I also want proper documentation so successful programs can be continued by future officers. Student concerns should be collected regularly and communicated to the appropriate people. The Learner Government should become an organization students trust because it demonstrates consistency and accountability. My vision is for student government to become a practical environment where students learn how to serve others, communicate respectfully, solve problems, and become responsible members of their community.", "makaTaoDescription": "T", "makaDiyosDescription": "E", "makabansaDescription": "G", "makakalikasanProject": "I", "makakalikasanDescription": "N"}', true, true, true, true, true, null, null, 'low');

ON CONFLICT (student_id, election_period_id) DO NOTHING;

-- =====================================================================
-- 052: parties are election-scoped, so a candidate may only reference a
-- party of its OWN election period.  The row above ships with a null
-- party_id because its party id is data-dependent (052 clones a party
-- per period); resolve it by name + period here.
-- =====================================================================
UPDATE public.candidates c
SET party_id = p.id
FROM public.parties p
WHERE p.name = 'LINGKOD Party'
  AND p.election_period_id = c.election_period_id
  AND c.id = 'c8164da9-df80-4824-9415-77b36bf88c60';

-- Any other candidate still pointing at another period's party is
-- re-pointed at the same-name party of its own period.
UPDATE public.candidates c
SET party_id = own_party.id
FROM public.parties own_party
WHERE own_party.id <> c.party_id
  AND own_party.election_period_id = c.election_period_id
  AND own_party.name = (select name from public.parties where id = c.party_id);
